contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool callAsOwner) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // We will attempt to call sudicideAnyone once; caller is always this contract (deployer of C)
        // Record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Make the state-changing call to c as a top-level statement and capture whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General invariant: either the call reverted, or C's balance is zero and this contract's balance did not decrease
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }
    receive() external payable { }
}

