// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool callAsOwner) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }

    function testFuzz_run(bool callAsOwner) public {
        _run(callAsOwner);
    }

    receive() external payable { }
}
